import{_ as i,o,c as t,ae as a}from"./chunks/framework.DICTGE3h.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"note/我的项目/后端协作.md","filePath":"note/我的项目/后端协作.md"}'),e={name:"note/我的项目/后端协作.md"};function u(r,l,p,q,s,d){return o(),t("div",null,[...l[0]||(l[0]=[a(`<p>你现在是一名资深的前端工程师，这个是我的简历：/Users/btclass/github/blog/src/note/我的项目/我的简历.md，你需要针对简历进行向我一个个提问，提问方向包括如下：</p><ol><li>与后端团队的配合。</li><li>深扒简历，简历上的项目整体流程（考察真实性 是不是自己落地的）。</li><li>场景题，问该怎么干活，跟技术面八股文什么的有差别，更多的是考验具体场景。</li><li>跟同事的关系，HW的文化，什么是艰苦奋斗，有哪些艰苦奋斗的经历。</li><li>压力测试：薪资、加班、业务范围。</li></ol><h2 id="前后端协作" tabindex="-1">前后端协作 <a class="header-anchor" href="#前后端协作" aria-label="Permalink to &quot;前后端协作&quot;">​</a></h2><p>我觉得前后端协作可以从协作流程和沟通机制两个层面来看。 ▎ ▎ 一、按项目阶段看协作流程： ▎ ▎ 1. 需求评审阶段：前后端要一起参与，明确边界——哪些逻辑放前端、哪些放后端，避免 ▎ 后期扯皮。 ▎ 2. 接口设计阶段：这是最关键的一环。我们一般会用 Swagger / Apifox ▎ 提前定好接口契约，包括字段、类型、错误码、分页规则等，前端可以基于 Mock ▎ 先开发，后端并行实现，提升效率。 ▎ 3. 联调阶段：要有统一的错误码规范和日志 traceId，方便快速定位问题边界。 ▎ 4. 上线后：需要监控告警、日志埋点，明确出问题时谁先响应。 ▎ ▎ 二、技术方案要有前瞻性。 我之前踩过一个坑：登录方案最初用 userId + ▎ token，后来出于安全和续期需求，升级成 accessToken + ▎ refreshToken，导致前后端大面积重构。复盘下来，鉴权、分页、错误码、时间格式这类 ▎ 底层约定，最好在项目启动时就按业界成熟方案定好，避免后期返工。 ▎ ▎ 三、沟通机制层面： ▎ ▎ - 重要决策书面化，沉淀到文档或 IM 记录里，避免&quot;口头说过&quot;的扯皮； ▎ - 出现分歧时，对事不对人，用数据和场景说话； ▎ - 如果确实推不动，及时拉 Leader ▎ 或第三方（比如测试、产品）对齐，而不是硬扛或妥协，避免影响项目进度。</p><hr><p>一句话亮点话术（可以背一句）</p><p>▎ &quot;前后端协作的核心是契约先行、边界清晰、问题可追溯，本质上是用工程规范减少沟通 ▎ 成本。&quot;</p><h2 id="对加班的看法" tabindex="-1">对加班的看法 <a class="header-anchor" href="#对加班的看法" aria-label="Permalink to &quot;对加班的看法&quot;">​</a></h2><p>我对加班的态度是：理解、接受，但也会主动去减少不必要的加班。 ▎ ▎ 技术是为业务服务的，当业务有紧迫性时，加班是正常的职业状态。我们现在大小周、活 ▎ 动期间经常加班，这些我都能接受，因为目标是清晰的。 ▎ ▎ 作为前端 Leader，我对自己的要求更高一些。下班时间或周末，如果用户或客服在群里 ▎ 反馈了线上问题，我会第一时间响应——因为这是我的职责，我愿意承担这个责任。 ▎ ▎ 但我也在思考怎么让团队加班更少、更高效： ▎ - 做好知识沉淀，不让团队反复踩同一个坑。不要重复造轮子。 ▎ - 活动上线前做充分的压测和预案，减少上线后救火的情况； ▎ - 建立完善的线上监控和告警，问题能更早暴露，不等到用户反馈才知道； ▎ ▎ ▎ 我的理想状态是：关键时刻能顶上，日常状态下高效收工，而不是用加班时长来证明投入度。</p><hr><p>一句话亮点话术</p><p>▎ &quot;我不排斥加班，但更在意的是——用工程手段让加班变得越来越少。&quot;</p><p>这句话体现了你的工程师思维和Leader 格局，比单纯说&quot;我不怕加班&quot;高一个层次。</p><h2 id="关于华为的文化-什么是艰苦奋斗-有哪些艰苦奋斗的经历" tabindex="-1">关于华为的文化，什么是艰苦奋斗，有哪些艰苦奋斗的经历 <a class="header-anchor" href="#关于华为的文化-什么是艰苦奋斗-有哪些艰苦奋斗的经历" aria-label="Permalink to &quot;关于华为的文化，什么是艰苦奋斗，有哪些艰苦奋斗的经历&quot;">​</a></h2><p>我对艰苦奋斗的理解是：在没有现成答案、资源也不充足的情况下，依然能扛住压力、为 ▎ 业务把事情做成。它不是单纯的&quot;加班&quot;或&quot;吃苦&quot;，而是一种面对困难时的主动担当。 ▎ ▎ 我自己印象最深的一段经历是从 0 到 1 搭建低代码平台。 ▎ ▎ 背景：当时业务侧每个活动页研发周期要 1-2 周，活动节奏越来越快，研发已经成为业 ▎ 务瓶颈。我们决定自研低代码平台来解决这个问题。 ▎ ▎ 困难： ▎ - 团队没人做过低代码，没有现成经验可参考； ▎ - 业务等不及，给的窗口期只有 3 个月； ▎ - 还要兼顾日常需求，没法全员投入。 ▎ ▎ 我的做法： ▎ 1. 先立框架不求完美：把项目拆成&quot;立项→技术选型→模块拆分→分期交付&quot;，先聚焦最核心 ▎ 的可视化搭建和物料体系，非核心功能放后期； ▎ 2. 借力业界经验：研究了阿里、字节的低代码方案，把能借鉴的架构思路吸收过来，避 ▎ 免重复造轮子； ▎ 3. 快速迭代验证：每周和业务对齐 demo，确保方向不跑偏； ▎ 4. 以身作则：作为 Leader，遇到硬骨头我自己先啃，加班加点把核心 schema ▎ 协议和渲染引擎啃下来。 ▎ ▎ 结果：3 个月内交付第一版，活动页研发周期从 1-2 周缩短到 1-2 ▎ 天，后续支撑了几百场活动，得到了业务和领导的认可。 ▎ ▎ 这件事让我体会到，艰苦奋斗的本质不是&quot;熬&quot;，而是在不确定中找到路径，并且坚持走下 ▎ 去。</p><pre><code>一句话亮点话术
</code></pre><p>▎ &quot;艰苦奋斗对我来说，不是比谁更能熬，而是在最难的事情上，能不能扛住并且做成。&quot;</p><h2 id="反问" tabindex="-1">反问 <a class="header-anchor" href="#反问" aria-label="Permalink to &quot;反问&quot;">​</a></h2><p>🌟 第一梯队：展现格局和战略思考</p><ol><li>业务方向类（最推荐）</li></ol><p>▎ &quot;想请教您，未来 1-2 ▎ 年这个业务/部门最重要的目标是什么？前端团队在其中扮演什么角色？&quot;</p><ul><li>为什么好：体现你关心业务而不只是技术，想知道自己能创造什么价值。</li><li>加分：听完后可以接一句&quot;如果我加入，我可以在 XX 方向上贡献力量&quot;。</li></ul><ol start="2"><li>团队挑战类</li></ol><p>▎ &quot;您觉得目前团队最大的挑战是什么？ 是技术层面的，还是组织协作或人才结构上的？&quot;</p><ul><li>为什么好：展现你愿意解决问题、不怕困难，契合&quot;艰苦奋斗&quot;价值观。</li></ul><ol start="3"><li>期待类</li></ol><p>▎ &quot;如果我有幸加入，您对我未来 3-6 个月最核心的期待是什么？ ▎ 哪些事情做成了，您会觉得这个人招对了？&quot;</p><ul><li>为什么好：极强的目标感和结果导向，大领导喜欢这种候选人。</li></ul><hr><p>🌟 第二梯队：展现思考深度</p><ol start="4"><li>文化/价值观类</li></ol><p>▎ &quot;您在这家公司这么多年，最认可的文化是什么？ ▎ 您觉得什么样的人在这里能发展得比较好？&quot;</p><ul><li>为什么好：让大领导谈他的价值观，他会很愿意聊，且能让你判断是否匹配。</li></ul><ol start="5"><li>行业判断类</li></ol><p>▎ &quot;您怎么看 XX 技术趋势 / 行业变化 对我们这个业务的影响？团队有没有相关的布局？&quot;</p><ul><li>例如：AI 对前端的影响、低代码趋势、跨端方案等</li><li>为什么好：体现你有行业视野，不是只埋头干活的人。</li></ul><hr><p>🌟 第三梯队：稳妥不踩雷</p><ol start="6"><li>个人成长类</li></ol><p>▎ &quot;您带过这么多技术人，您觉得一个前端 Leader ▎ 想要继续往上走，最关键的能力是什么？&quot;</p><ul><li>为什么好：向大领导请教，对方有表达欲，同时显示你有上进心。</li></ul><ol start="7"><li>决策类（适合更高层级）</li></ol><p>▎ &quot;公司/部门最近有什么重要的战略决策或调整，可以分享的？&quot;</p><ul><li>仅限 VP 级别以上，且氛围比较开放时使用。</li></ul><h2 id="我的问题" tabindex="-1">我的问题 <a class="header-anchor" href="#我的问题" aria-label="Permalink to &quot;我的问题&quot;">​</a></h2><ol><li>您觉得目前团队最大的挑战是什么？ 是技术层面的，还是组织协作或人才结构上的？</li><li>您怎么看 XX 技术趋势 / 行业变化 对我们这个业务的影响？团队有没有相关的布局？AI 对前端的影响</li><li>您在这家公司这么多年，最认可的文化是什么？您觉得什么样的人在这里能发展得比较好？</li></ol><h2 id="场景题回答" tabindex="-1">场景题回答 <a class="header-anchor" href="#场景题回答" aria-label="Permalink to &quot;场景题回答&quot;">​</a></h2><p>通用四步框架</p><ol><li>澄清需求（30秒-1分钟） 不要急着答。先问清楚边界：</li></ol><ul><li>规模：QPS 多少？数据量多大？用户量级？</li><li>场景：读多写少还是写多读少？实时性要求？</li><li>约束：一致性要求强不强？预算/团队规模？</li><li>目标：是要解决性能、可用性，还是功能本身？</li></ul><p>▎ 例：&quot;设计一个短链系统&quot; → 问&quot;日活多少？短链需要永久有效吗？需要统计点击数吗？&quot;</p><ol start="2"><li><p>给出粗略方案（讲整体架构） 先画大图：客户端 → 接入层 → 业务层 → 存储层。把数据流和关键组件说出来，不纠结细节。</p></li><li><p>深入关键点（重点） 挑 1-2 个核心难点深入：</p></li></ol><ul><li>存储选型与表结构 / 数据分片</li><li>缓存策略（穿透、雪崩、一致性）</li><li>高并发瓶颈与扩展方式</li><li>一致性 vs 可用性的取舍</li></ul><ol start="4"><li>主动谈权衡和演进 说&quot;我目前选 A，因为……；如果场景变成 X，我会切到 B&quot;。再聊监控、降级、容量规划。</li></ol><p>常见误区</p><ul><li>❌ 不澄清就开干，方案跑偏</li><li>❌ 上来就堆技术名词（Redis、Kafka、ES 一把梭）</li><li>❌ 只讲 happy path，不谈失败处理、数据倾斜、热点 key</li><li>❌ 把方案讲死，不主动给替代项</li></ul><p>加分动作</p><ul><li>用数字说话：估算 QPS、存储量、带宽（容量估算很加分）</li><li>主动提非功能性需求：可观测性、灰度、回滚</li><li>承认不确定：&quot;这块我没在生产用过，但我会先做小流量验证</li></ul><p>前端场景题四步框架</p><ol><li>澄清需求 前端的&quot;边界问题&quot;和后端不同，重点问：</li></ol><ul><li>场景与用户：PC 还是移动？弱网吗？低端机要支持吗？国际化？</li><li>数据规模：列表有多少条？图片多大？一次渲染多少 DOM 节点？</li><li>交互要求：需要离线吗？需要实时同步吗？SEO 要不要？</li><li>技术约束：现有技术栈？浏览器兼容到哪个版本？团队规模？</li></ul><p>▎ 例：&quot;实现一个无限滚动列表&quot; → ▎ 问&quot;单条数据大小？总条数？要不要支持往回滚动定位？移动端还是 PC？&quot;</p><ol start="2"><li>分层给方案 前端方案通常按这几层展开：</li></ol><ul><li>渲染层：DOM 结构、虚拟列表、懒加载、骨架屏</li><li>数据层：状态管理、缓存、请求合并/去重、分页策略</li><li>网络层：接口设计、预加载、CDN、HTTP 缓存</li><li>工程层：打包、代码分割、监控、降级</li></ul><ol start="3"><li>深入核心难点 挑能体现深度的点细讲。前端高频深入方向：</li></ol><ul><li>性能：首屏、LCP/FCP、长任务拆分、requestIdleCallback</li><li>渲染：重排重绘、合成层、will-change、虚拟滚动原理</li><li>大数据量：分片渲染、Web Worker、IndexedDB</li><li>状态：跨组件通信、并发更新、乐观更新与回滚</li><li>兼容与降级：浏览器特性检测、polyfill 策略</li></ul><ol start="4"><li>谈权衡和监控</li></ol><ul><li>SSR vs CSR vs SSG 怎么选</li><li>体积 vs 速度怎么取舍</li><li>怎么做线上监控（性能指标、白屏、JS 错误、接口失败）</li></ul>`,68)])])}const c=i(e,[["render",u]]);export{h as __pageData,c as default};
